import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"艳阳天气","description":"","frontmatter":{"title":"艳阳天气","date":"2026-11-20T00:00:00.000Z","seq":204,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词","prev":{"text":"轻蹑罗鞋掩绛绡","link":"/blogs/全宋词·柳永/轻蹑罗鞋掩绛绡.html"},"next":{"text":"繁华锦烂","link":"/blogs/全宋词·柳永/繁华锦烂.html"}},"headers":[],"relativePath":"blogs/全宋词·柳永/艳阳天气.md","filePath":"blogs/全宋词·柳永/艳阳天气.md"}'),o={name:"blogs/全宋词·柳永/艳阳天气.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="艳阳天气" tabindex="-1">艳阳天气 <a class="header-anchor" href="#艳阳天气" aria-label="Permalink to &quot;艳阳天气&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　夜半乐</p><div class="poem"><p class="poem-stanza">艳阳天气，烟雨风暖，芳郊澄朗闲凝伫。</p><p class="poem-stanza">渐妆点亭台，参差佳树。</p><p class="poem-stanza">舞腰困力，垂杨绿映，浅桃秾李夭夭，嫩红无数。</p><p class="poem-stanza">度绮燕、流莺斗双语。</p><p class="poem-stanza">翠娥南陌簇簇，蹑影红阴，缓移娇步。</p><p class="poem-stanza">抬粉面、韶容花光相妒。</p><p class="poem-stanza">绛绡袖举。</p><p class="poem-stanza">云鬟风颤，半遮檀口含羞，背人偷顾。</p><p class="poem-stanza">竞斗草、金钗笑争赌。</p><p class="poem-stanza">对此嘉景，顿觉消凝，惹成愁绪。</p><p class="poem-stanza">念解佩、轻盈在何处。</p><p class="poem-stanza">忍良时、孤负少年等闲度。</p><p class="poem-stanza">空望极、回首斜阳暮。</p><p class="poem-stanza">叹浪萍风梗知何去。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
